class Solution {
public:
    bool isValid(string s) {
        vector<char> st;
        unordered_map<char, char> mp = {{')', '('}, {']', '['}, {'}', '{'}};
        for (char c : s) {
            auto it = mp.find(c);
            if (it != mp.end()) {
                if (st.empty() || st.back() != it->second) return false;
                st.pop_back();
            } else {
                st.push_back(c);
            }
        }
        return st.empty();
    }
};

