class Solution {
    public boolean isValid(String s) {
        Deque<Character> st = new ArrayDeque<>();
        Map<Character, Character> mp = Map.of(')', '(', ']', '[', '}', '{');
        for (char c : s.toCharArray()) {
            if (mp.containsKey(c)) {
                if (st.isEmpty() || st.pop() != mp.get(c)) return false;
            } else {
                st.push(c);
            }
        }
        return st.isEmpty();
    }
}
